  // ─── Render ────────────────────────────────────────────────────────────────
  function chip(name) { return el("span", { "class": "raci-chip" }, [name]); }

  // Items visible under the current scope (All / an Activity / a sub-activity) +
  // search box. Scope encodes the tree slice: "all" | "act:<n>" | "sub:<id>".
  // A search keeps every match PLUS its ancestor chain, so the hierarchy stays
  // intact (a deep project hit still shows its sub-activity + Activity header).
  function visibleMatrixItems() {
    var scope = state.mfilter.scope || "all";
    var q = (state.mfilter.q || "").trim().toLowerCase();
    var items = state.items;

    // 1. Scope → inScope key set (null = everything).
    var inScope = null;
    if (scope.indexOf("act:") === 0) {
      var an = scope.slice(4); inScope = {};
      items.forEach(function (it) { if (it.activity === an) inScope[it.key] = true; });
    } else if (scope.indexOf("sub:") === 0) {
      var subKey = "project:" + scope.slice(4); inScope = {};
      items.forEach(function (it) {
        if (it.key === subKey || it.ancestors.indexOf(subKey) >= 0) inScope[it.key] = true;
      });
      var subItem = items.filter(function (it) { return it.key === subKey; })[0];
      if (subItem) subItem.ancestors.forEach(function (k) { inScope[k] = true; }); // Activity header for context
    }

    // 2. Query → keep matches + their ancestors (within scope).
    var keep = {};
    items.forEach(function (it) {
      if (inScope && !inScope[it.key]) return;
      if (q) {
        if ((it.id + " " + it.name).toLowerCase().indexOf(q) >= 0) {
          keep[it.key] = true;
          it.ancestors.forEach(function (k) { keep[k] = true; });
        }
      } else {
        keep[it.key] = true;
      }
    });

    return items.filter(function (it) { return keep[it.key]; });
  }

  function fillMatrixTable(holder) {
    var canEdit = !!state.sess;
    holder.innerHTML = "";
    var tbl = el("table", { "class": "raci-table" }, []);
    var rerun = function () { fillMatrixTable(holder); };
    var head = el("tr", {}, [
      sortableTh("Activity / Project", "item", state.msort, rerun, { "class": "raci-th-item" })
    ].concat(
      ROLES.map(function (r) {
        return sortableTh(r.k + " · " + r.label, r.k, state.msort, rerun, { title: r.label + " — " + r.desc });
      })));
    tbl.appendChild(head);
    var items = visibleMatrixItems();
    // When a column sort is active, FLATTEN the tree into a flat sorted list
    // (each row carries its full id, so it stays self-describing without the
    // nesting). col=null keeps the 3-tier tree order.
    var sorted = state.msort.col != null;
    if (sorted) {
      var c = state.msort.col, dir = state.msort.dir;
      items = items.slice().sort(function (a, b) {
        if (c === "item") return cmpVals(a.id, b.id, dir) || (a.isActivity ? -1 : 1);
        var an = names(raciFor(a)[c]).join(", "), bn = names(raciFor(b)[c]).join(", ");
        return cmpVals(an, bn, dir) || natCmp(a.id, b.id);
      });
    }
    items.forEach(function (item) {
      var rc = raciFor(item);
      var rowCls = item.isActivity ? "raci-row-act" : (item.isSub ? "raci-row-sub" : "raci-row-proj");
      var tr = el("tr", { "class": rowCls, "data-raci-key": item.type + ":" + item.id,
        "data-depth": String(item.depth) }, []);
      var itemCell = el("td", { "class": "raci-item-cell",
        style: "padding-left:" + (0.6 + (sorted ? 0 : item.depth * 1.15)) + "rem;" }, [
        el("span", { "class": "raci-item-id" }, [item.isActivity ? "Activity " + item.id : item.id]),
        el("span", { "class": "raci-item-name" }, [item.name]),
        item.isSub ? el("span", { "class": "raci-tier-tag", title: "Workplan sub-activity" }, ["sub-activity"]) : null]);
      // ⧉ copy — only when a reviewer is signed in AND this row has ≥1 assignment.
      // Lives in the item cell (no click handler of its own), so no conflict with
      // the RACI cells' openRoleEditor.
      if (canEdit && hasAny(rc)) {
        var cpBtn = el("button", { "class": "raci-copy-btn",
          title: "Copy this row's R/A/C/I to other rows" }, ["⧉ copy"]);
        (function (src) {
          cpBtn.addEventListener("click", function (e) { e.stopPropagation(); openCopyRaci(src); });
        })(item);
        itemCell.appendChild(cpBtn);
      }
      // 📝 update — view the card's update history (anyone); post one (signed-in).
      var nUp = updatesFor(item).length;
      var upBtn = el("button", { "class": "raci-upd-btn" + (nUp ? " has" : ""),
        title: canEdit ? "Add / view status updates for this item" : "View status updates" },
        ["📝" + (nUp ? " " + nUp : "")]);
      (function (it) { upBtn.addEventListener("click", function (e) { e.stopPropagation(); openUpdate(it); }); })(item);
      itemCell.appendChild(upBtn);
      // 📣 per-item nudge — on EVERY row when signed in, so a reviewer can nudge
      // just this one item's Responsible/Accountable people (emails the card + a
      // composer link). The Directory opt-out still applies inside
      // itemNudgeRecipients (opted-out members are never emailed); openItemNudge
      // alerts gracefully when a row has no one eligible to nudge yet.
      if (canEdit) {
        var inBtn = el("button", { "class": "raci-itemnudge-btn",
          title: "Nudge this item's Responsible/Accountable people — emails the card + a link to update it" }, ["📣"]);
        (function (it) { inBtn.addEventListener("click", function (e) { e.stopPropagation(); openItemNudge(it); }); })(item);
        itemCell.appendChild(inBtn);
      }
      tr.appendChild(itemCell);
      ROLES.forEach(function (role) {
        var cell = el("td", { "class": "raci-cell" + (canEdit ? " raci-cell-edit" : ""),
          title: canEdit ? "Click to assign " + role.label : "" }, []);
        var ns = names(rc[role.k]);
        if (ns.length) ns.forEach(function (n) { cell.appendChild(chip(n)); });
        else cell.appendChild(el("span", { "class": "raci-empty" }, [canEdit ? "+ assign" : "—"]));
        if (canEdit) cell.addEventListener("click", function () { openRoleEditor(item, role.k); });
        tr.appendChild(cell);
      });
      tbl.appendChild(tr);
    });
    if (!items.length) tbl.appendChild(el("tr", {}, [
      el("td", { colspan: String(ROLES.length + 1), "class": "raci-empty", style: "padding:.8rem .6rem;" },
        ["No Activities or Projects match this filter."])]));
    holder.appendChild(tbl);
    var nShown = items.filter(function (i) { return !i.isActivity; }).length;
    var total = state.items.filter(function (i) { return !i.isActivity; }).length;
    var countKids = [
      (state.mfilter.scope === "all" && !state.mfilter.q)
        ? total + " sub-activities & projects across 4 Activities"
        : "Showing " + nShown + " of " + total + " sub-activities & projects"];
    // When a sort is active the tree is flattened — offer a one-click way back.
    if (sorted) {
      var reset = el("button", { "class": "raci-tree-reset",
        title: "Clear the column sort and restore the Activity → sub-activity → project tree" },
        ["⤺ tree view"]);
      reset.addEventListener("click", function () { state.msort.col = null; state.msort.dir = 1; fillMatrixTable(holder); });
      countKids.push(el("span", { "class": "raci-sort-note" }, [" · sorted by column — "]));
      countKids.push(reset);
    }
    holder.appendChild(el("div", { "class": "raci-count" }, countKids));
  }

  function renderMatrix() {
    var wrap = el("div", { "class": "raci-matrix-wrap" }, []);
    var holder = el("div", { "class": "raci-table-holder" }, []);

    // Filter bar: a hierarchical scope dropdown (Activity → its sub-activities)
    // + search box (matrix view only). optgroups group each Activity's
    // sub-activities under it; "▸ All of Activity N" selects the whole subtree.
    var sel = el("select", { "class": "raci-in raci-filter-sel",
      title: "Filter to an Activity or one of its sub-activities" },
      [el("option", { value: "all" }, ["All Activities & sub-activities"])].concat(
        ACTIVITIES.map(function (a) {
          var subs = (state._subByAct[a.id] || []).map(function (s) {
            return el("option", { value: "sub:" + s.id }, [s.id + "  " + s.name]);
          });
          return el("optgroup", { label: "Activity " + a.id + " — " + a.name },
            [el("option", { value: "act:" + a.id }, ["▸ All of Activity " + a.id])].concat(subs));
        })));
    sel.value = state.mfilter.scope;
    sel.addEventListener("change", function () { state.mfilter.scope = sel.value; fillMatrixTable(holder); });
    var search = el("input", { type: "search", "class": "raci-in raci-filter-q",
      placeholder: "Find an Activity, sub-activity, or project…" });
    search.value = state.mfilter.q;
    search.addEventListener("input", function () { state.mfilter.q = search.value; fillMatrixTable(holder); });
    var clear = el("button", { "class": "raci-btn raci-filter-clear", title: "Clear filters" }, ["Clear"]);
    clear.addEventListener("click", function () {
      state.mfilter.scope = "all"; state.mfilter.q = "";
      sel.value = "all"; search.value = ""; fillMatrixTable(holder);
    });
    // Manual nudge — signed-in only; drafts a mailto to the opted-in team.
    var nudgeBtn = null;
    if (state.sess) {
      nudgeBtn = el("button", { "class": "raci-btn raci-filter-nudge",
        title: "Email ALL opted-in team members for status updates (opens your mail app — nothing is auto-sent). Use a row's 📣 to nudge just that one item." },
        ["📣 Nudge All"]);
      nudgeBtn.addEventListener("click", openNudge);
    }
    wrap.appendChild(el("div", { "class": "raci-filter-bar" }, [sel, search, clear, nudgeBtn]));

    fillMatrixTable(holder);
    wrap.appendChild(holder);
    return wrap;
  }

  function patchMember(m, field, value) {
    var body = {}; body[field] = (value === "" ? null : value);
    return sbWrite("PATCH", "team_members?id=eq." + encodeURIComponent(m.id), body, "return=minimal");
  }

  // A click-to-edit Team Directory cell (name / role / email). Read-only for
  // anonymous viewers; a signed-in reviewer clicks to edit, Enter/blur saves
  // (optimistic, rolls back on failure), Esc cancels.
  function editCell(m, field, cls) {
    var td = el("td", { "class": cls || "" }, []);
    function show() {
      td.innerHTML = "";
      var v = m[field];
      if (field === "email" && v && !state.sess) td.appendChild(el("a", { href: "mailto:" + v }, [v]));
      else if (v) td.appendChild(document.createTextNode(v));
      else td.appendChild(el("span", { "class": "raci-empty" }, [state.sess ? "+ add" : "—"]));
      if (state.sess) { td.classList.add("raci-edit-cell"); td.title = "Click to edit"; }
    }
    function edit() {
      if (!state.sess || td.querySelector("input")) return;
      td.innerHTML = "";
      var inp = el("input", { type: field === "email" ? "email" : "text", "class": "raci-in raci-cell-in" });
      inp.value = m[field] || "";
      td.appendChild(inp); inp.focus(); inp.select();
      var done = false;
      function save() {
        if (done) return; done = true;
        var nv = inp.value.trim();
        if (nv === (m[field] || "")) { show(); return; }
        var old = m[field]; m[field] = nv; show();
        patchMember(m, field, nv).then(function (r) { if (!r.ok) throw new Error(); })
          .catch(function () { m[field] = old; show(); alert("Could not save — are you a signed-in reviewer?"); });
      }
      inp.addEventListener("keydown", function (e) {
        if (e.key === "Enter") { e.preventDefault(); save(); }
        else if (e.key === "Escape") { done = true; show(); }
      });
      inp.addEventListener("blur", save);
    }
    show();
    if (state.sess) td.addEventListener("click", function () { edit(); });
    return td;
  }

  function renderDirectory() {
    var canEdit = !!state.sess;
    // Column-header check-all / clear-all for the nudge opt-in (signed-in only).
    var emailMembers = state.members.filter(function (m) { return m.email; });
    var onCount = emailMembers.filter(function (m) { return m.nudge !== false; }).length;
    var allCb = el("input", { type: "checkbox", "class": "raci-nudge-cb raci-nudge-all" });
    allCb.checked = !!emailMembers.length && onCount === emailMembers.length;
    allCb.indeterminate = onCount > 0 && onCount < emailMembers.length;
    allCb.disabled = !canEdit || !emailMembers.length;
    allCb.title = canEdit ? "Check all / clear all" : "Sign in to change";
    allCb.addEventListener("change", function () { setAllNudge(allCb.checked); });
    var nudgeTh = el("th", { "class": "raci-th-nudge", title: "Include members in the update nudges" }, [
      el("div", { "class": "raci-th-nudge-wrap" }, ["Nudge for Updates",
        canEdit ? el("label", { "class": "raci-nudge-all-lbl", title: "Check all / clear all" },
          [allCb, el("span", {}, ["all"])]) : null])]);
    var tbl = el("table", { "class": "raci-table raci-dir" }, [
      el("tr", {}, [
        sortableTh("Name", "name", state.dsort, render),
        sortableTh("Role / title", "role", state.dsort, render),
        sortableTh("Email", "email", state.dsort, render),
        nudgeTh,
        sortableTh("Last nudged", "nudged", state.dsort, render, { "class": "raci-th-nudge", title: "When this member was last nudged" }),
        sortableTh("Status", "status", state.dsort, render, { "class": "raci-th-nudge", title: "Whether a response has been recorded since the last nudge" })])]);
    // Sort a COPY (never mutate state.members order — the matrix + saves rely on it).
    var dmembers = state.members.slice();
    if (state.dsort.col) {
      var dc = state.dsort.col, ddir = state.dsort.dir;
      dmembers.sort(function (a, b) {
        if (dc === "nudged") return cmpVals(a.last_nudged_at, b.last_nudged_at, ddir) || natCmp(a.name, b.name);
        if (dc === "status") return cmpVals(statusRank(a), statusRank(b), ddir) || natCmp(a.name, b.name);
        return cmpVals(a[dc], b[dc], ddir) || natCmp(a.name, b.name);
      });
    }
    dmembers.forEach(function (m) {
      var on = m.nudge !== false; // default true
      var cb = el("input", { type: "checkbox", "class": "raci-nudge-cb" });
      cb.checked = on; cb.disabled = !canEdit || !m.email;
      cb.title = !m.email ? "Add an email before enabling nudges" : (canEdit ? "" : "Sign in to change");
      if (canEdit && m.email) cb.addEventListener("change", function () { toggleNudge(m, cb); });
      // Last-nudged + response-status cells (the accountability columns).
      var nudgedTd = el("td", { "class": "raci-nudged-cell" }, [m.last_nudged_at ? relTime(m.last_nudged_at) : "—"]);
      var st = nudgeStatus(m);
      var statusTd = el("td", { "class": "raci-status-cell " + st.cls }, [st.txt]);
      if (canEdit) {
        statusTd.title = "Click to mark this member as having responded now";
        statusTd.style.cursor = "pointer";
        statusTd.addEventListener("click", function () { markResponded(m); });
      }
      tbl.appendChild(el("tr", { "class": on ? "" : "raci-row-muted" }, [
        editCell(m, "name", "raci-dir-n"),
        editCell(m, "role", "raci-dir-r"),
        editCell(m, "email", "raci-dir-e"),
        el("td", { "class": "raci-nudge-cell" }, [cb]),
        nudgedTd, statusTd]));
    });
    var nudgeOn = state.members.filter(function (m) { return m.nudge !== false && m.email; }).length;
    var head = el("div", { "class": "raci-dir-head" }, [
      el("span", {}, [state.members.length + " team members · " +
        state.members.filter(function (m) { return m.email; }).length + " with email · " +
        nudgeOn + " set to nudge"])]);
    if (canEdit) head.appendChild(el("button", { "class": "raci-btn raci-btn-go", onclick: openAddMember }, ["+ Add member"]));
    return el("div", {}, [head, tbl,
      el("div", { "class": "raci-legend" }, [canEdit
        ? "Uncheck a member to hold them out of the update nudges (re-check to re-enable anytime)."
        : "“Nudge for Updates” controls who receives the weekly update reminders — sign in to change."])]);
  }

  // Check-all / clear-all the nudge opt-in for every member with an email.
  // Optimistic re-render, then one PATCH per changed member; rolls back on error.
  function setAllNudge(want) {
    if (!state.sess) { alert("Sign in to change nudges."); return; }
    var targets = state.members.filter(function (m) { return m.email && (m.nudge !== false) !== want; });
    if (!targets.length) { render(); return; }
    targets.forEach(function (m) { m.nudge = want; });
    render();
    Promise.all(targets.map(function (m) {
      return sbWrite("PATCH", "team_members?id=eq." + encodeURIComponent(m.id), { nudge: want }, "return=minimal")
        .then(function (r) { if (!r.ok) throw new Error("save failed (" + r.status + ")"); });
    })).catch(function () {
      targets.forEach(function (m) { m.nudge = !want; }); render();
      alert("Could not update all members — are you a signed-in reviewer?");
    });
  }

  // ─── Manual nudge (mailto draft to the opted-in team) ──────────────────────
  // v1 channel = a mailto: draft: opens the reviewer's mail app pre-addressed
  // to every member opted in for nudges (nudge !== false AND has an email), so
  // nothing is auto-sent — the reviewer reviews + clicks send. Auto-send via a
  // Teams webhook / Graph sendMail is a later upgrade (handoff decision #1).
  function nudgeRecipients() {
    return state.members.filter(function (m) { return m.email && m.nudge !== false; });
  }
  function buildNudgeHref() {
    var recips = nudgeRecipients();
    if (!recips.length) return null;
    // Semicolon-delimited — Outlook (the team's client) rejects comma-separated
    // recipient lists in mailto drafts (Sam, 2026-07-02).
    var emails = recips.map(function (m) { return m.email; }).join(";");
    var subject = "CPL Workplan — quick update request";
    var url = location.origin + location.pathname + "#raci";
    var body = "Hi team,\n\nPlease reply with a short status update on your CPL workplan "
      + "items (your Responsible / Accountable assignments) — even if there's nothing new, "
      + "just reply \"no activity this period\" so we know you're current.\n\n"
      + "Your items live here: " + url + "\n\nThank you!\n";
    return "mailto:" + encodeURIComponent(emails)
      + "?subject=" + encodeURIComponent(subject) + "&body=" + encodeURIComponent(body);
  }
  // Record that a nudge was fired at each opted-in member (last_nudged_at = now),
  // so the directory can show who's been nudged + who's gone quiet. Optimistic;
  // best-effort PATCH (the mailto is the real action).
  function stampNudged() {
    if (!state.sess) return;
    var recips = nudgeRecipients();
    if (!recips.length) return;
    var now = new Date().toISOString();
    recips.forEach(function (m) { m.last_nudged_at = now; });
    if (state.view === "directory") render();
    recips.forEach(function (m) {
      sbWrite("PATCH", "team_members?id=eq." + encodeURIComponent(m.id), { last_nudged_at: now }, "return=minimal");
    });
  }
  function openNudge() {
    var href = buildNudgeHref();
    if (!href) { alert("No team members are opted in for nudges. Set them in the Team Directory."); return; }
    stampNudged();
    window.location.href = href;
  }

  // ─── Per-item nudge (Phase 2): email THIS item's R/A people, quote the card,
  // and link straight to its update composer (?update=<key>#raci → openUpdate).
  function itemNudgeRecipients(item) {
    var rc = raciFor(item), seen = {}, out = [];
    // Honor the Team Directory "Nudge for Updates" opt-out: a member a reviewer
    // has unchecked (nudge === false) is never emailed — by the team blast OR a
    // per-item nudge. Recipients not in the directory default to included.
    var optedOut = {};
    (state.members || []).forEach(function (m) {
      if (m && m.email && m.nudge === false) optedOut[m.email.toLowerCase()] = 1;
    });
    ["R", "A"].forEach(function (k) {
      (rc[k] || []).forEach(function (m) {
        var e = m && m.email; if (!e) return;
        var lc = e.toLowerCase();
        if (optedOut[lc] || seen[lc]) return;
        seen[lc] = 1; out.push(m);
      });
    });
    return out;
  }
  function buildItemNudgeHref(item) {
    var recips = itemNudgeRecipients(item);
    if (!recips.length) return null;
    // Semicolon-delimited for Outlook (see buildNudgeHref).
    var emails = recips.map(function (m) { return m.email; }).join(";");
    var c = cplItem(item);
    // Land on the Activities & Projects tab (NOT #raci) — card_actions.js reads the
    // ?update= param there and opens the composer in place (Sam, 2026-06-29).
    var link = location.origin + location.pathname + "?update=" + encodeURIComponent(item.key) + "#activities-projects";
    var subject = "CPL update request — " + (item.isActivity ? "Activity " + item.id : item.id) + " " + c.name;
    var body = "Hi,\n\nQuick status check on your CPL workplan item:\n\n" + itemSummaryText(item)
      + "\n\nPlease share a few details — even \"no activity this period\" is helpful. "
      + "Click here and braindump a couple lines; CC will write it up for you:\n" + link
      + "\n\nThank you!\n";
    return "mailto:" + encodeURIComponent(emails)
      + "?subject=" + encodeURIComponent(subject) + "&body=" + encodeURIComponent(body);
  }
  function stampItemNudged(item) {
    if (!state.sess) return;
    var want = {}; itemNudgeRecipients(item).forEach(function (m) { want[(m.email || "").toLowerCase()] = 1; });
    var now = new Date().toISOString();
    var hit = state.members.filter(function (m) { return m.email && want[m.email.toLowerCase()]; });
    hit.forEach(function (m) { m.last_nudged_at = now; });
    if (state.view === "directory") render();
    hit.forEach(function (m) { sbWrite("PATCH", "team_members?id=eq." + encodeURIComponent(m.id), { last_nudged_at: now }, "return=minimal"); });
  }
  function openItemNudge(item) {
    var href = buildItemNudgeHref(item);
    if (!href) { alert("No one to nudge on this item — its Responsible/Accountable people either have no email or are opted out of nudges in the Team Directory."); return; }
    stampItemNudged(item);
    window.location.href = href;
  }

  // ─── In-place card actions (no redirect to the RACI tab) ───────────────────
  // The Activity / Project cards' 📝 Update + 📣 Nudge affordances open the popup
  // RIGHT THERE on the Activities & Projects tab instead of bouncing to #raci
  // (Sam, 2026-06-29). card_actions.js intercepts the card-link clicks (and the
  // nudge-email ?update= deep-link) and calls these. We ensure the data + CSS are
  // loaded first (this script is lazy — the RACI tab may never have been opened),
  // then open the existing composer / nudge modal. The same phrase-unlock box the
  // composer grew lets the user edit without leaving the tab.
  function withItem(key, fn) {
    function go() {
      ensureCss();
      var it = (state.items || []).filter(function (x) { return x.key === key; })[0];
      if (it) fn(it); else alert("Couldn't find that workplan item — try the Team & RACI tab.");
    }
    if (state.loaded) go(); else load(go);
  }
  function openCardUpdate(key) { withItem(key, openUpdate); }
  function openCardNudge(key) { withItem(key, openItemNudge); }
  // Relative time for the directory's nudge-status columns.
  function relTime(iso) {
    if (!iso) return "";
    var t = new Date(iso).getTime();
    if (isNaN(t)) return "";
    var days = Math.floor((Date.now() - t) / 86400000);
    if (days <= 0) return "today";
    if (days === 1) return "1d ago";
    if (days < 30) return days + "d ago";
    var mo = Math.floor(days / 30);
    return mo + "mo ago";
  }
  // Response status for a member: responded (✓) when last_response_at is at or
  // after the last nudge; otherwise awaiting (overdue ≥7d), or — if never nudged.
  // Sort key for the directory "Status" column: responded (1) → awaiting (2,
  // overdue first within awaiting) → never-nudged (3). String-keyed for cmpVals.
  function statusRank(m) {
    var nud = m.last_nudged_at ? new Date(m.last_nudged_at).getTime() : 0;
    var resp = m.last_response_at ? new Date(m.last_response_at).getTime() : 0;
    if (nud && resp >= nud) return "1";
    if (nud) {
      var days = Math.floor((Date.now() - nud) / 86400000);
      // Larger overdue first → invert days into the key.
      return "2_" + String(1e9 - days).padStart(12, "0");
    }
    return "3";
  }
  function nudgeStatus(m) {
    var nud = m.last_nudged_at ? new Date(m.last_nudged_at).getTime() : 0;
    var resp = m.last_response_at ? new Date(m.last_response_at).getTime() : 0;
    if (resp && resp >= nud) return { txt: "✓ responded " + relTime(m.last_response_at), cls: "raci-st-ok" };
    if (nud) {
      var days = Math.floor((Date.now() - nud) / 86400000);
      return { txt: "⏳ awaiting" + (days >= 1 ? " " + days + "d" : ""),
        cls: days >= 7 ? "raci-st-overdue" : "raci-st-wait" };
    }
    return { txt: "—", cls: "raci-st-none" };
  }

  // Mark a member as having responded now (sets last_response_at). Reviewer-only;
  // optimistic re-render, rolls back on error. Auto-set later when the braindump
  // composer lands (posting an update records a response).
  function markResponded(m) {
    if (!state.sess) { alert("Sign in to record a response."); return; }
    var now = new Date().toISOString();
    var prev = m.last_response_at; m.last_response_at = now; render();
    sbWrite("PATCH", "team_members?id=eq." + encodeURIComponent(m.id), { last_response_at: now }, "return=minimal")
      .then(function (r) { if (!r.ok) throw new Error(); })
      .catch(function () { m.last_response_at = prev; render(); alert("Could not save — are you a signed-in reviewer?"); });
  }

  function toggleNudge(m, cb) {
    var want = cb.checked;
    cb.disabled = true;
    sbWrite("PATCH", "team_members?id=eq." + encodeURIComponent(m.id), { nudge: want }, "return=minimal")
      .then(function (r) {
        if (!r.ok) throw new Error();
        m.nudge = want; cb.disabled = false;
        var tr = cb.closest("tr"); if (tr) tr.className = want ? "" : "raci-row-muted";
        var head = document.querySelector(".raci-dir-head span");
        if (head) { var n = state.members.filter(function (x) { return x.nudge !== false && x.email; }).length;
          head.textContent = head.textContent.replace(/\d+ set to nudge/, n + " set to nudge"); }
      })
      .catch(function () { cb.checked = !want; cb.disabled = false; alert("Could not save — are you a signed-in reviewer?"); });
  }

  // ─── Deep-link focus (per-card "RACI" link on Activities & Projects) ────────
  // A card sets sessionStorage['cpl_raci_focus'] = "project:5.1" / "activity:4"
  // then navigates to #raci. We consume it on every tab activation (the
  // cpl-tab-activated listener) AND at the end of the first boot render (the
  // cold deep-link case, where the activation event fired before this script
  // loaded), then scroll the matrix to that row and flash it.
  var FOCUS_KEY = "cpl_raci_focus";
  var UPDATE_KEY = "cpl_update_focus";
  var NUDGE_KEY = "cpl_nudge_focus";
  function consumePendingFocus() {
    if (!state.loaded) return; // leave the key for boot's render callback
    // (a) Update deep-link — the nudge email links to a specific item's update
    // composer (Phase 2). Accept either a ?update=<type>:<id> query param (the
    // email URL) or sessionStorage cpl_update_focus (in-app cards). Opens the
    // braindump composer straight away.
    var u = null;
    try {
      var qp = new URLSearchParams(location.search || "");
      u = qp.get("update") || sessionStorage.getItem(UPDATE_KEY);
      if (qp.get("update")) { qp.delete("update"); var qs = qp.toString();
        history.replaceState(null, "", location.pathname + (qs ? "?" + qs : "") + location.hash); }
      sessionStorage.removeItem(UPDATE_KEY);
    } catch (e) {}
    if (u && u.indexOf(":") > 0) {
      var it = state.items.filter(function (x) { return x.key === u; })[0];
      if (it) { focusItem(it.type, it.id); openUpdate(it); return; }
    }
    // (a2) Nudge deep-link — the per-card 📣 Nudge button. Focus the row, then
    // open its per-item nudge (drafts the email to its Responsible/Accountable
    // people). Set by the Activity / sub-activity / project cards via
    // sessionStorage cpl_nudge_focus = "activity:N" | "project:<id>".
    var nd = null;
    try { nd = sessionStorage.getItem(NUDGE_KEY); if (nd) sessionStorage.removeItem(NUDGE_KEY); } catch (e) {}
    if (nd && nd.indexOf(":") > 0) {
      var ni = state.items.filter(function (x) { return x.key === nd; })[0];
      if (ni) { focusItem(ni.type, ni.id); openItemNudge(ni); return; }
    }
    // (b) RACI row focus (per-card 👥 RACI link).
    var f = null;
    try { f = sessionStorage.getItem(FOCUS_KEY); } catch (e) {}
    if (!f) return;
    try { sessionStorage.removeItem(FOCUS_KEY); } catch (e) {}
    var i = f.indexOf(":");
    if (i < 0) return;
    focusItem(f.slice(0, i), f.slice(i + 1));
  }
  function focusItem(type, id) {
    // Make the row reachable: matrix view, filters cleared, then re-render.
    state.view = "matrix";
    state.mfilter = { scope: "all", q: "" };
    render();
    var sel = '[data-raci-key="' + type + ":" + (id || "").replace(/"/g, "") + '"]';
    var row = document.querySelector(sel);
    if (!row) return;
    if (typeof row.scrollIntoView === "function") {
      try { row.scrollIntoView({ behavior: "smooth", block: "center" }); } catch (e) {}
    }
    row.classList.add("raci-row-focus");
    setTimeout(function () { row.classList.remove("raci-row-focus"); }, 2600);
  }

  function render() {
    ensureCss();
    var root = document.getElementById("raci-root");
    if (!root) return;
    root.innerHTML = "";

    // Header + intro
    root.appendChild(el("div", { "class": "raci-intro" }, [
      el("h2", {}, ["Team & RACI"]),
      el("p", {}, ["Assign Responsibility, Accountability, Consultation, and Information for every workplan Activity and Project — the same people then receive the update nudges. Targets live on the ",
        el("a", { href: "#workplan-goals" }, ["Annual Workplan Goals"]), " tab."])]));

    // Auth + view toggle bar
    var bar = el("div", { "class": "raci-bar" }, []);
    var toggle = el("div", { "class": "raci-toggle" }, [
      mkToggle("matrix", "RACI Matrix"), mkToggle("directory", "Team Directory")]);
    bar.appendChild(toggle);
    bar.appendChild(renderAuth());
    root.appendChild(bar);

    root.appendChild(state.view === "directory" ? renderDirectory() : renderMatrix());
    if (state.view === "matrix") root.appendChild(el("div", { "class": "raci-legend" }, [
      "R Responsible · A Accountable · C Consulted · I Informed" +
      (state.sess ? "  —  click any cell to assign people" : "  —  sign in to edit")]));
  }
  function mkToggle(view, label) {
    return el("button", { "class": "raci-tg" + (state.view === view ? " on" : ""),
      onclick: function () { state.view = view; render(); } }, [label]);
  }
  function renderAuth() {
    var w = el("div", { "class": "raci-auth" }, []);
    if (state.sess) {
      var who = state.sess.teamPass ? "team phrase" : (state.sess.email || "(no email)");
      w.appendChild(el("span", {}, ["✓ Editing unlocked (", who, ")"]));
      // Shown to phrase users too, now that it just opens the Team Phrases TAB.
      // Hiding it was half of why Sam lost track of it: a phrase holder had no
      // way to learn the surface existed. The tab states plainly that viewing
      // needs a reviewer sign-in, which is a better answer than an absent button.
      w.appendChild(el("button", {
        "class": "raci-btn",
        title: "Open the Team Phrases tab — viewing or changing a phrase needs a reviewer sign-in",
        onclick: openPhraseAdmin
      }, ["⚙ Manage team phrases"]));
      w.appendChild(el("button", { "class": "raci-btn", onclick: function () { signOut(); load(render); } }, ["Lock"]));
    } else {
      var inp = el("input", { type: "password", placeholder: "team phrase", "class": "raci-in" });
      var st = el("span", { "class": "raci-auth-msg" }, []);
      var btn = el("button", { "class": "raci-btn raci-btn-go" }, ["🔓 Unlock editing"]);
      function tryUnlock() {
        var p = (inp.value || "").trim();
        if (!p) { st.textContent = "Enter the team phrase."; return; }
        st.textContent = "Checking…"; btn.disabled = true;
        unlockWithPhrase(p).then(function (ok) {
          btn.disabled = false;
          if (!ok) { st.textContent = "That phrase doesn't match — ask a reviewer for the current one."; return; }
          load(render);
        });
      }
      btn.addEventListener("click", tryUnlock);
      inp.addEventListener("keydown", function (e) { if (e.key === "Enter") tryUnlock(); });
      w.appendChild(el("span", { "class": "raci-auth-lbl" }, ["Team phrase to edit: "]));
      w.appendChild(inp); w.appendChild(btn); w.appendChild(st);
      // The phrase is the right credential for THIS tab, but it does not open
      // the reviewer-only ones (Admin, Team Phrases). Say where that sign-in is
      // instead of leaving someone to conclude it no longer exists — which is
      // exactly what happened when the magic-link box was removed from here.
      w.appendChild(el("span", { "class": "raci-auth-hint" }, [
        "Editing Admin or Team Phrases needs a personal sign-in instead — ℹ About, top right."]));
    }
    return w;
  }
  // The phrase admin is its own TAB now (team_phrases.js, #team-phrases) —
  // Sam, 2026-08-12: "I lost track of where Manage team phrases is. It should
  // be a tab that requires a magic link to view." It was a modal only a
  // signed-in reviewer ever saw, buried in this auth bar, so a phrase holder
  // never knew it existed. This keeps the familiar button and sends it there
  // rather than carrying a second implementation of the same editor.
  function openPhraseAdmin() {
    if (window.CPL_TABS && typeof window.CPL_TABS.navigate === "function") {
      window.CPL_TABS.navigate("team-phrases");
      return;
    }
    location.hash = "#team-phrases";
  }

